{
  "name": "rx_adv_packet_process",
  "confidence": "medium",
  "docstring": "Enqueues a received advertising-packet payload into RX descriptor-ring slots, splitting the data across ring blocks, updating buffer addresses and lengths, and clearing the RF RX interrupt when the ring is exhausted.",
  "subsystem": "mm",
  "var_renames": {
    "a1": "rx_desc_ring",
    "a2": "packet_len",
    "a3": "packet_buf",
    "a4": "offset_ptr",
    "a5": "slot_index",
    "v6": "desc_block",
    "v7": "slot_offset",
    "v8": "rx_mode",
    "v9": "irq_flag_ptr",
    "v10": "desc_slot",
    "v13": "remaining_len",
    "v16": "next_desc_slot",
    "v17": "tail_offset",
    "v18": "end_offset_plus_one",
    "v19": "slot_capacity",
    "v22": "orig_offset_ptr"
  },
  "struct_hints": [
    {
      "offset": 4,
      "meaning": "next descriptor block pointer in the RX descriptor ring"
    },
    {
      "offset": 8,
      "meaning": "current tail/offset within the descriptor block"
    },
    {
      "offset": 12,
      "meaning": "end/head offset limit within the descriptor block"
    },
    {
      "offset": 20,
      "meaning": "first descriptor slot offset after the block header"
    },
    {
      "offset": 0,
      "meaning": "descriptor slot field 0: computed buffer/address word"
    },
    {
      "offset": 4,
      "meaning": "descriptor slot field 1: packet buffer address pointer"
    },
    {
      "offset": 8,
      "meaning": "descriptor slot field 2: DMA/status control word with length and high control bits"
    },
    {
      "offset": 12,
      "meaning": "descriptor slot field 3: transferred chunk length"
    },
    {
      "offset": 32,
      "meaning": "descriptor slot field 8: next descriptor slot pointer in mode 3"
    }
  ]
}
